{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows early signs of bearishness (e.g., sentiment < 0.00).",
    "Increase forecast sensitivity to recent price spikes — if price rises sharply, model should overcorrect slightly to avoid overshoot.",
    "Apply mean reversion bias: if forecast is significantly below recent 7-day average, gently raise it toward historical mean.",
    "For long-term horizons (>14 days), reduce forecast volatility — avoid overreacting to short-term sentiment swings.",
    "When sentiment is positive and price is trending upward, slightly increase forecast to capture momentum, but cap at 10% above recent peak.",
    "If model consistently underpredicts during high sentiment periods, add a 5–10% upward bias to forecast for bullish sentiment windows."
  ]
}
